css:
@page {
    size: 7.8cm auto;
    margin: 2mm;
}

body {
    width: 7.8cm;
    margin: 0;
    padding: 0;
    font-family: "Courier New", monospace;
    font-size: 11px;
    line-height: 1.2;
}

hr {
    border: 0;
    border-top: 1px solid #000;
    margin: 0;
    padding: 0;
    height: 0;
}

.ticket {
    width: 7.8cm;
}

.center {
    text-align: center;
}

.right {
    text-align: right;
}

.timestamp {
    font-size: 11px;
    padding-top: 7px;
}


.info-table,
.items-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 11px;
}

.info-table td {
    padding: 1px 0;
    vertical-align: top;
}

.info-table .label {
    width: 34%;
    font-weight: bold;
}

.items-table th {
    border-bottom: 1px solid #000;
    text-align: left;
    padding: 2px 0;
}

.items-table td {
    padding: 2px 0;
    vertical-align: top;
}

.items-table th:nth-child(2),
.items-table th:nth-child(3),
.items-table th:nth-child(4),
.items-table td:nth-child(2),
.items-table td:nth-child(3),
.items-table td:nth-child(4) {
    text-align: center;
}
